remove.example:
// A three-day ban: the script keeps the end date, then lifts it.
const ban = player.ban('Griefing, 3 days');
if (ban) {
  saveUnban(ban.id, Date.now() + 3 * 24 * 3600 * 1000);
}

// Later, when the time is up:
kcds.core.Bans.remove(ban.id);

remove.exampleCs:
// A three-day ban: the script keeps the end date, then lifts it.
var ban = player.Ban("Griefing, 3 days");
if (ban)
{
    saveUnban.Invoke(ban["id"], DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + 3 * 24 * 3600 * 1000);
}

// Later, when the time is up:
Bans.Remove(ban["id"]);

